/**
 * TPSI — Michigan Democratic U.S. Senate Primary
 * County-level forecast seed data · Election August 4, 2026
 *
 * Generated from DSMeridian Model 10 post-stratified onto a 19,999-record
 * voter-file universe, with turnout modelled from the 2024 Democratic primary
 * baseline adjusted for registration growth and observed early-vote intensity.
 *
 * DO NOT EDIT BY HAND — regenerate from the model pipeline.
 *
 * READ BEFORE USING COUNTY MARGINS:
 * County margins are not survey findings. Geography replicates poorly across the
 * two survey modes (r = +0.15, versus +0.98 for age), so the region term was shrunk
 * to 15% weight. County variation reflects demographic composition, not local
 * political texture. `projectedTurnout` is materially more reliable than `margin`:
 * turnout derives from observed voter-file behaviour across 19,999 records, while
 * vote shares rest on 254 completed interviews spread across the state.
 * 49 of 83 counties have a 90% interval that crosses 50/50 — see `tooCloseToCall`.
 */

export type Candidate = "elSayed" | "stevens" | "mcmorrow";

export type Region =
  | "Wayne"
  | "Oakland"
  | "Macomb"
  | "RestSoutheast"
  | "MidMichiganThumb"
  | "WestNorth";

export interface CountyForecast {
  /** 5-digit state+county FIPS code */
  fips: string;
  name: string;
  region: Region;
  /** Modelled Democratic primary ballots cast */
  projectedTurnout: number;
  /** Percent of the projected statewide electorate */
  shareOfElectorate: number;
  /** Vote shares, percent of all ballots cast in county */
  elSayed: number;
  stevens: number;
  mcmorrow: number;
  /** elSayed - stevens, percentage points */
  margin: number;
  /** El-Sayed share of the two-way (El-Sayed + Stevens) */
  twoWayElSayed: number;
  /** 90% bootstrap interval on twoWayElSayed */
  ci90: [number, number];
  /** True when ci90 straddles 50 — do not report a winner */
  tooCloseToCall: boolean;
  elSayedVotes: number;
  stevensVotes: number;
}

export interface StatewideForecast {
  projectedTurnout: number;
  elSayed: number;
  stevens: number;
  mcmorrow: number;
  margin: number;
  elSayedVotes: number;
  stevensVotes: number;
  mcmorrowVotes: number;
  /** Simulated probability El-Sayed finishes first */
  winProbabilityElSayed: number;
  medianMargin: number;
  /** 90% interval on the simulated margin */
  margin90: [number, number];
}

export interface TurnoutModel {
  base2024: number;
  netRegistrationGrowthPct: number;
  grossRegistrationGrowthPct: number;
  excitementMultiplier: number;
  projected: number;
  projected90: [number, number];
  activeRegisteredVoters: number;
  pctOfActiveRv: number;
}

export interface ForecastMeta {
  model: string;
  electionDate: string;
  builtAt: string;
  fieldDates: string;
  interviewsCollected: number;
  interviewsReported: number;
  voterUniverseRecords: number;
  marginOfError: number;
  simulations: number;
  totalSdPoints: number;
  mcmorrowProtestShareOfUndecided: number;
  countiesTooCloseToCall: number;
  regionShrinkage: number;
}

