/* ------------------------------------------------------------------ */
/* Lookups and helpers                                                 */
/* ------------------------------------------------------------------ */

export const COUNTIES_BY_FIPS: Record<string, CountyForecast> =
  Object.fromEntries(COUNTY_FORECASTS.map((c) => [c.fips, c]));

export const COUNTIES_BY_NAME: Record<string, CountyForecast> =
  Object.fromEntries(COUNTY_FORECASTS.map((c) => [c.name.toLowerCase(), c]));

export function getCounty(key: string): CountyForecast | undefined {
  return COUNTIES_BY_FIPS[key] ?? COUNTIES_BY_NAME[key.toLowerCase()];
}

export function countiesByRegion(region: Region): CountyForecast[] {
  return COUNTY_FORECASTS.filter((c) => c.region === region);
}

/** Counties whose 90% interval excludes 50 — the only ones safe to call. */
export function decidedCounties(): CountyForecast[] {
  return COUNTY_FORECASTS.filter((c) => !c.tooCloseToCall);
}

/** Sum of projected turnout across a set of counties. */
export function totalTurnout(counties: CountyForecast[] = COUNTY_FORECASTS): number {
  return counties.reduce((sum, c) => sum + c.projectedTurnout, 0);
}

/**
 * Cumulative share of the statewide electorate held by the n largest counties.
 * Useful for "the top four counties are half the vote" framing.
 */
export function cumulativeShare(n: number): number {
  return COUNTY_FORECASTS.slice(0, n).reduce((s, c) => s + c.shareOfElectorate, 0);
}

export function leader(c: CountyForecast): Candidate | null {
  if (c.tooCloseToCall) return null;
  return c.margin > 0 ? "elSayed" : "stevens";
}
